core_reasoning_1:
\textbf{Claim.} For the affine-Toda bion potential
\[
V(\vec z)=V_0\sum_{i=1}^{N}\left|e^{\vec\alpha_i\cdot\vec z}-e^{\vec\alpha_{i-1}\cdot\vec z}\right|^2,
\]
with affine root \(\vec\alpha_N=-(\vec\alpha_1+\cdots+\vec\alpha_{N-1})\), the zero-energy constant vacua have representatives
\[
\vec z_k=\frac{2\pi i k}{N}\vec\rho,\qquad k=0,1,\ldots,N-1,
\]
and satisfy \(e^{\vec\alpha_i\cdot\vec z_k}=e^{2\pi i k/N}\) for all \(i=1,\ldots,N\).

\textbf{Premises.}
\begin{align*}
(P1)\quad & N\geq2,\quad V_0>0,\quad \vec\alpha_0:=\vec\alpha_N,
\quad \vec\alpha_N:=-(\vec\alpha_1+\cdots+\vec\alpha_{N-1}).\\
(P2)\quad & V(\vec z)=V_0\sum_{i=1}^{N}\left|e^{\vec\alpha_i\cdot\vec z}-e^{\vec\alpha_{i-1}\cdot\vec z}\right|^2.\\
(P3)\quad & \vec\rho:=\vec\mu_1+\cdots+\vec\mu_{N-1},\quad
\vec\alpha_i\cdot\vec\rho=1\ (1\leq i\leq N-1),\quad
\vec\alpha_N\cdot\vec\rho=1-N.\\
(P4)\quad & \sum_{i=1}^{N}\vec\alpha_i=\vec 0.\\
(P5)\quad & e^a e^b=e^{a+b},\quad |u|^2=0\Longleftrightarrow u=0,
\quad q^N=1\Longleftrightarrow q=e^{2\pi i k/N}\text{ for }k=0,\ldots,N-1.\\
(P6)\quad & \text{Inequivalent representatives are identified by the dual-photon weight-lattice periodicity.}
\end{align*}

\textbf{Derivation.}
\begin{align*}
V(\vec z)=0
&\Longleftrightarrow \left|e^{\vec\alpha_i\cdot\vec z}-e^{\vec\alpha_{i-1}\cdot\vec z}\right|^2=0\quad (i=1,\ldots,N) && \text{by (P2), }V_0>0\\
&\Longleftrightarrow e^{\vec\alpha_i\cdot\vec z}=e^{\vec\alpha_{i-1}\cdot\vec z}\quad (i=1,\ldots,N) && \text{by (P5)}\\
&\Longleftrightarrow e^{\vec\alpha_1\cdot\vec z}=\cdots=e^{\vec\alpha_N\cdot\vec z}=:q. && \text{transitivity}
\end{align*}
\begin{align*}
1
&=e^{\vec 0\cdot\vec z} && \text{zero vector}\\
&=e^{(\sum_{i=1}^{N}\vec\alpha_i)\cdot\vec z} && \text{by (P4)}\\
&=e^{\sum_{i=1}^{N}(\vec\alpha_i\cdot\vec z)} && \text{linearity of the dot product}\\
&=\prod_{i=1}^{N}e^{\vec\alpha_i\cdot\vec z} && \text{by (P5)}\\
&=q^N. && \text{definition of }q
\end{align*}
\begin{align*}
q^N=1
&\Longleftrightarrow q=e^{2\pi i k/N},\quad k=0,1,\ldots,N-1. && \text{by (P5)}
\end{align*}
For \(\vec z_k:=2\pi i k\vec\rho/N\),
\begin{align*}
e^{\vec\alpha_i\cdot\vec z_k}
&=\exp\left(\frac{2\pi i k}{N}\vec\alpha_i\cdot\vec\rho\right) && \text{definition of }\vec z_k\\
&=\exp\left(\frac{2\pi i k}{N}\right),\quad 1\leq i\leq N-1, && \text{by (P3)}\\
e^{\vec\alpha_N\cdot\vec z_k}
&=\exp\left(\frac{2\pi i k}{N}(1-N)\right) && \text{by (P3)}\\
&=\exp\left(\frac{2\pi i k}{N}\right)\exp(-2\pi i k) && \text{by (P5)}\\
&=\exp\left(\frac{2\pi i k}{N}\right). && k\in\mathbb Z
\end{align*}
Thus the \(N\) representatives \(\vec z_k\) realize all possible zero-energy values of \(q\), and (P6) removes periodic copies.

\textbf{Final Result.}
\[
\boxed{V(\vec z_k)=0,\quad \vec z_k=\frac{2\pi i k}{N}\vec\rho,\quad e^{\vec\alpha_i\cdot\vec z_k}=e^{2\pi i k/N}\ (i=1,\ldots,N),\quad k=0,\ldots,N-1.}
\]
\hfill$\blacksquare$

core_reasoning_2:
\textbf{Claim.} With unit 't Hooft flux through the two compact two-tori, the fractional vortex sector has \(|Q_{\mathrm{top}}|=1/N\), and any configuration in that sector obeys the Yang-Mills action bound
\[
S_v\geq \frac{S_I}{N},\qquad S_I:=\frac{8\pi^2}{g^2}.
\]

\textbf{Premises.}
\begin{align*}
(P1)\quad & N\geq2,
\quad n_{12}=1,
\quad n_{34}=1.\\
(P2)\quad & Q_{\mathrm{top}}\in -\frac{n_{12}n_{34}}{N}+\mathbb Z.\\
(P3)\quad & \text{The minimal fractional vortex representatives in this sector have }Q_{\mathrm{top}}=\pm\frac{1}{N}.\\
(P4)\quad & S_v=\frac{1}{g^2}\int \operatorname{tr}(f\wedge \star f),\quad g^2>0.\\
(P5)\quad & S_v\geq \frac{8\pi^2}{g^2}|Q_{\mathrm{top}}|.\\
(P6)\quad & S_I:=\frac{8\pi^2}{g^2}.
\end{align*}

\textbf{Derivation.}
\begin{align*}
Q_{\mathrm{top}}
&\in -\frac{n_{12}n_{34}}{N}+\mathbb Z && \text{by (P2)}\\
&= -\frac{1\cdot 1}{N}+\mathbb Z && \text{by (P1)}\\
&= -\frac{1}{N}+\mathbb Z. && \text{arithmetic}
\end{align*}
For the minimal fractional representatives,
\begin{align*}
|Q_{\mathrm{top}}|
&=\left|\pm\frac{1}{N}\right| && \text{by (P3)}\\
&=\frac{1}{N}. && N>0
\end{align*}
Substitution into the action bound gives
\begin{align*}
S_v
&\geq \frac{8\pi^2}{g^2}|Q_{\mathrm{top}}| && \text{by (P5)}\\
&=\frac{8\pi^2}{g^2}\frac{1}{N} && \text{previous line}\\
&=\frac{S_I}{N}. && \text{by (P6)}
\end{align*}

\textbf{Final Result.}
\[
\boxed{|Q_{\mathrm{top}}|=\frac{1}{N},\qquad S_v\geq \frac{S_I}{N}.}
\]
\hfill$\blacksquare$

core_reasoning_4:
\textbf{Claim.} The center-twisted boundary conditions for the holonomy and dual photon imply
\[
\vec z(x,x_3+L_3)=P_W^{-1}\vec z(x,x_3),
\]
and the constant configurations \(\vec z_k=2\pi i k\vec\rho/N\), \(k=0,\ldots,N-1\), satisfy this condition modulo the dual-photon weight-lattice periodicity.

\textbf{Premises.}
\begin{align*}
(P1)\quad & \vec z:=i\left[\vec\sigma+\left(\frac{\theta}{2\pi}+\frac{4\pi i}{g^2}\right)(\vec\varphi-\vec\varphi_c)\right].\\
(P2)\quad & \vec\varphi_c:=\frac{2\pi}{N}\vec\rho.\\
(P3)\quad & P_W\vec\rho=\vec\rho-N\vec\mu_1.\\
(P4)\quad & \vec\sigma(x,x_3)=P_W\vec\sigma(x,x_3+L_3).\\
(P5)\quad & \vec\varphi(x,x_3)=P_W\vec\varphi(x,x_3+L_3)+2\pi\vec\mu_1.\\
(P6)\quad & \vec z\sim \vec z+2\pi i\vec\mu\quad \text{for each integral weight }\vec\mu.\\
(P7)\quad & \vec z_k:=2\pi i k\vec\rho/N,\quad k\in\{0,1,\ldots,N-1\}.
\end{align*}

\textbf{Derivation.}
First,
\begin{align*}
P_W\vec\varphi_c
&=P_W\left(\frac{2\pi}{N}\vec\rho\right) && \text{by (P2)}\\
&=\frac{2\pi}{N}P_W\vec\rho && \text{linearity}\\
&=\frac{2\pi}{N}(\vec\rho-N\vec\mu_1) && \text{by (P3)}\\
&=\vec\varphi_c-2\pi\vec\mu_1. && \text{by (P2)}
\end{align*}
Let \(x_3':=x_3+L_3\). Then
\begin{align*}
P_W\vec z(x,x_3')
&=i\left[P_W\vec\sigma(x,x_3')+\left(\frac{\theta}{2\pi}+\frac{4\pi i}{g^2}\right)(P_W\vec\varphi(x,x_3')-P_W\vec\varphi_c)\right] && \text{by (P1)}\\
&=i\left[\vec\sigma(x,x_3)+\left(\frac{\theta}{2\pi}+\frac{4\pi i}{g^2}\right)(\vec\varphi(x,x_3)-2\pi\vec\mu_1-\vec\varphi_c+2\pi\vec\mu_1)\right] && \text{by (P4), (P5)}\\
&=i\left[\vec\sigma(x,x_3)+\left(\frac{\theta}{2\pi}+\frac{4\pi i}{g^2}\right)(\vec\varphi(x,x_3)-\vec\varphi_c)\right] && \text{cancel }\pm2\pi\vec\mu_1\\
&=\vec z(x,x_3). && \text{by (P1)}
\end{align*}
Therefore,
\begin{align*}
P_W\vec z(x,x_3+L_3)=\vec z(x,x_3)
&\Longleftrightarrow \vec z(x,x_3+L_3)=P_W^{-1}\vec z(x,x_3). && \text{apply }P_W^{-1}
\end{align*}
For \(\vec z_k\),
\begin{align*}
P_W\vec z_k
&=P_W\left(\frac{2\pi i k}{N}\vec\rho\right) && \text{by (P7)}\\
&=\frac{2\pi i k}{N}(\vec\rho-N\vec\mu_1) && \text{by (P3)}\\
&=\vec z_k-2\pi i k\vec\mu_1 && \text{by (P7)}\\
&\sim \vec z_k. && \text{by (P6)}
\end{align*}
Thus \(\vec z_k\sim P_W^{-1}\vec z_k\), so each \(\vec z_k\) is an allowed constant mode.

\textbf{Final Result.}
\[
\boxed{\vec z(x,x_3+L_3)=P_W^{-1}\vec z(x,x_3),\qquad \vec z_k=\frac{2\pi i k}{N}\vec\rho\text{ satisfies this modulo }2\pi i\Lambda_{\mathrm{weights}}.}
\]
\hfill$\blacksquare$

core_reasoning_5:
\textbf{Claim.} A BPS/KK monopole in the center-twisted compactification carries center-vortex flux: if a fundamental Wilson loop \(W(C)\) surrounds the localized flux, then \(W(C)=e^{-2\pi i/N}\); if it does not surround the flux, then \(W(C)=1\).

\textbf{Premises.}
\begin{align*}
(P1)\quad & \vec\nu_1,\ldots,\vec\nu_N\text{ are defining-representation weights with }\vec\nu_\ell\cdot\vec\nu_i=\delta_{\ell i}-\frac{1}{N}.\\
(P2)\quad & W(C):=\frac{1}{N}\sum_{\ell=1}^{N}\exp\left(i\vec\nu_\ell\cdot\oint_C\vec a\right).\\
(P3)\quad & \oint_C\vec a=2\pi\vec\nu_i\quad \text{if }C\text{ surrounds the localized flux}.\\
(P4)\quad & \oint_C\vec a=\vec0\quad \text{if }C\text{ does not surround the localized flux}.\\
(P5)\quad & e^{2\pi i m}=1\quad \text{for every }m\in\mathbb Z.
\end{align*}

\textbf{Derivation.}
Case 1: \(C\) surrounds the localized flux.
\begin{align*}
W(C)
&=\frac{1}{N}\sum_{\ell=1}^{N}\exp\left(i\vec\nu_\ell\cdot 2\pi\vec\nu_i\right) && \text{by (P2), (P3)}\\
&=\frac{1}{N}\sum_{\ell=1}^{N}\exp\left(2\pi i\left(\delta_{\ell i}-\frac{1}{N}\right)\right) && \text{by (P1)}\\
&=\frac{1}{N}\sum_{\ell=1}^{N}\exp(2\pi i\delta_{\ell i})\exp\left(-\frac{2\pi i}{N}\right) && \text{split the exponential}\\
&=\frac{1}{N}\sum_{\ell=1}^{N}e^{-2\pi i/N} && \text{by (P5), since }\delta_{\ell i}\in\{0,1\}\\
&=e^{-2\pi i/N}. && \text{sum }N\text{ equal terms}
\end{align*}
Case 2: \(C\) does not surround the localized flux.
\begin{align*}
W(C)
&=\frac{1}{N}\sum_{\ell=1}^{N}\exp(i\vec\nu_\ell\cdot\vec0) && \text{by (P2), (P4)}\\
&=\frac{1}{N}\sum_{\ell=1}^{N}1 && \text{because }e^0=1\\
&=1. && \text{sum }N\text{ equal terms}
\end{align*}

\textbf{Final Result.}
\[
\boxed{W(C)=\begin{cases}e^{-2\pi i/N},& C\text{ surrounds the localized flux},\\[2pt]1,& C\text{ does not surround the localized flux}.
\end{cases}}
\]
\hfill$\blacksquare$

core_reasoning_6:
\textbf{Claim.} The integrated-in two-dimensional superpotential
\[
W(Z,\Sigma)=N L_4\Lambda^3 e^{i\theta/N}e^Z+\Sigma(e^{NZ}-1)
\]
has \(N\) supersymmetric vacua
\[
e^{Z_k}=e^{2\pi i k/N},\qquad \Sigma_k=-L_4\Lambda^3 e^{i(\theta+2\pi k)/N},
\]
and, using the holomorphic-coupling extraction rule for the gluino bilinear, gives
\[
\langle\operatorname{tr}(\lambda\lambda)\rangle_k=16\pi^2\Lambda^3e^{i(\theta+2\pi k)/N}.
\]

\textbf{Premises.}
\begin{align*}
(P1)\quad & W(Z,\Sigma)=N L_4\Lambda^3 e^{i\theta/N}e^Z+\Sigma(e^{NZ}-1),\quad N\geq2.\\
(P2)\quad & \text{Supersymmetric vacua solve }\partial_\Sigma W=0\text{ and }\partial_ZW=0.\\
(P3)\quad & \partial_\Sigma[\Sigma(e^{NZ}-1)]=e^{NZ}-1.\\
(P4)\quad & \partial_Z e^Z=e^Z,\quad \partial_Z e^{NZ}=N e^{NZ}.\\
(P5)\quad & e^{NZ}=1\Longleftrightarrow e^Z=e^{2\pi i k/N}\text{ for }k=0,1,\ldots,N-1.\\
(P6)\quad & \langle\operatorname{tr}(\lambda\lambda)\rangle_k:=\frac{16\pi^2}{N L_4}\,\Lambda^3\frac{\partial W_k}{\partial(\Lambda^3)},\quad W_k:=W(Z_k,\Sigma_k).\\
(P7)\quad & e^a e^b=e^{a+b}.\\
(P8)\quad & \frac{\partial}{\partial(\Lambda^3)}\left(\Lambda^3 C\right)=C\quad\text{whenever }C\text{ is independent of }\Lambda^3.
\end{align*}

\textbf{Derivation.}
The \(\Sigma\)-equation is
\begin{align*}
0=\partial_\Sigma W
&=e^{NZ}-1 && \text{by (P1), (P3)}\\
&\Longleftrightarrow e^{NZ}=1. && \text{algebra}
\end{align*}
Thus
\begin{align*}
e^Z=e^{2\pi i k/N},\quad k=0,1,\ldots,N-1, && \text{by (P5)}
\end{align*}
and these are the \(N\) distinct roots selected by the constraint. The \(Z\)-equation is
\begin{align*}
0=\partial_ZW
&=N L_4\Lambda^3 e^{i\theta/N}e^Z+N\Sigma e^{NZ} && \text{by (P1), (P4)}\\
&=N L_4\Lambda^3 e^{i\theta/N}e^Z+N\Sigma && \text{using }e^{NZ}=1\\
&\Longleftrightarrow \Sigma=-L_4\Lambda^3 e^{i\theta/N}e^Z. && \text{divide by }N
\end{align*}
At the \(k\)-th root,
\begin{align*}
\Sigma_k
&=-L_4\Lambda^3 e^{i\theta/N}e^{2\pi i k/N} && \text{substitute }e^{Z_k}\\
&=-L_4\Lambda^3 e^{i(\theta+2\pi k)/N}. && \text{by (P7)}
\end{align*}
The constraint term vanishes on shell:
\begin{align*}
\Sigma_k(e^{NZ_k}-1)=0. && \text{because }e^{NZ_k}=1
\end{align*}
Therefore
\begin{align*}
W_k
&=N L_4\Lambda^3 e^{i\theta/N}e^{Z_k} && \text{by (P1), on-shell constraint}\\
&=N L_4\Lambda^3 e^{i\theta/N}e^{2\pi i k/N} && \text{vacuum root}\\
&=N L_4\Lambda^3 e^{i(\theta+2\pi k)/N}. && \text{by (P7)}
\end{align*}
Now apply the holomorphic-coupling extraction rule in derivative form:
\begin{align*}
\frac{\partial W_k}{\partial(\Lambda^3)}
&=\frac{\partial}{\partial(\Lambda^3)}\left(N L_4\Lambda^3 e^{i(\theta+2\pi k)/N}\right) && \text{substitute }W_k\\
&=N L_4 e^{i(\theta+2\pi k)/N} && \text{by (P8)}.
\end{align*}
Hence
\begin{align*}
\langle\operatorname{tr}(\lambda\lambda)\rangle_k
&=\frac{16\pi^2}{N L_4}\,\Lambda^3\frac{\partial W_k}{\partial(\Lambda^3)} && \text{by (P6)}\\
&=\frac{16\pi^2}{N L_4}\,\Lambda^3\left(N L_4 e^{i(\theta+2\pi k)/N}\right) && \text{substitute derivative}\\
&=16\pi^2\Lambda^3 e^{i(\theta+2\pi k)/N}. && \text{cancel }N L_4
\end{align*}

\textbf{Final Result.}
\[
\boxed{e^{Z_k}=e^{2\pi i k/N},\quad \Sigma_k=-L_4\Lambda^3 e^{i(\theta+2\pi k)/N},\quad \langle\operatorname{tr}(\lambda\lambda)\rangle_k=16\pi^2\Lambda^3e^{i(\theta+2\pi k)/N}.}
\]
\hfill$\blacksquare$

core_reasoning_7:
\textbf{Claim.} For a small real gluino mass \(m\), the \(k\)-th two-dimensional vacuum-energy branch is
\[
E_k(\theta)=-2L_3L_4m\Lambda^3\cos\left(\frac{\theta+2\pi k}{N}\right),
\]
and the branches \(k=0\) and \(k=N-1\) are degenerate at \(\theta=\pi\).

\textbf{Premises.}
\begin{align*}
(P1)\quad & m\in\mathbb R,
\quad E_k(\theta):=-L_3L_4m\left(\frac{1}{16\pi^2}\langle\operatorname{tr}(\lambda\lambda)\rangle_k+\mathrm{c.c.}\right).\\
(P2)\quad & \langle\operatorname{tr}(\lambda\lambda)\rangle_k=16\pi^2\Lambda^3e^{i(\theta+2\pi k)/N}.\\
(P3)\quad & e^{ia}+e^{-ia}=2\cos a\quad \text{for real }a.\\
(P4)\quad & \cos(2\pi-a)=\cos a.\\
(P5)\quad & L_3>0,\quad L_4>0,\quad \Lambda>0,
\quad N\geq2,
\quad k\in\{0,1,\ldots,N-1\}.
\end{align*}

\textbf{Derivation.}
Define
\begin{align*}
a_k:=\frac{\theta+2\pi k}{N}. && \text{definition}
\end{align*}
Then
\begin{align*}
E_k(\theta)
&=-L_3L_4m\left(\frac{1}{16\pi^2}\langle\operatorname{tr}(\lambda\lambda)\rangle_k+\mathrm{c.c.}\right) && \text{by (P1)}\\
&=-L_3L_4m\left(\Lambda^3e^{ia_k}+\Lambda^3e^{-ia_k}\right) && \text{by (P2), complex conjugation}\\
&=-L_3L_4m\Lambda^3(e^{ia_k}+e^{-ia_k}) && \text{factor }\Lambda^3\\
&=-2L_3L_4m\Lambda^3\cos a_k && \text{by (P3)}\\
&=-2L_3L_4m\Lambda^3\cos\left(\frac{\theta+2\pi k}{N}\right). && \text{substitute }a_k
\end{align*}
At \(\theta=\pi\), the two specified branches are
\begin{align*}
E_0(\pi)
&=-2L_3L_4m\Lambda^3\cos\left(\frac{\pi}{N}\right), && \text{set }k=0\\
E_{N-1}(\pi)
&=-2L_3L_4m\Lambda^3\cos\left(\frac{\pi+2\pi(N-1)}{N}\right) && \text{set }k=N-1\\
&=-2L_3L_4m\Lambda^3\cos\left(2\pi-\frac{\pi}{N}\right) && \text{algebra}\\
&=-2L_3L_4m\Lambda^3\cos\left(\frac{\pi}{N}\right) && \text{by (P4)}\\
&=E_0(\pi). && \text{compare with first line}
\end{align*}

\textbf{Final Result.}
\[
\boxed{E_k(\theta)=-2L_3L_4m\Lambda^3\cos\left(\frac{\theta+2\pi k}{N}\right),\qquad E_0(\pi)=E_{N-1}(\pi).}
\]
\hfill$\blacksquare$

core_reasoning_8:
\textbf{Claim.} In the center-twisted \(R^2\times (S^1)_3\) compactification of SU(\(N\)), the domain-wall configuration with jumps
\[
(\Delta\vec\sigma)_{\mathrm{upper}}=\frac{2\pi}{N}\vec\rho,
\qquad
(\Delta\vec\sigma)_{\mathrm{lower}}=-\frac{2\pi}{N}\vec\rho+2\pi\vec\mu_1
\]
satisfies both the fundamental Wilson-loop winding and the twisted gluing condition. Consequently,
\[
\langle W(C)\rangle\sim e^{-T_{\mathrm{conf}}\operatorname{Area}(C)}+e^{-T_{\mathrm{kink}}L_3\operatorname{Length}(C)},
\]
and for a square loop of side \(L\) the perimeter term dominates when \(L>4T_{\mathrm{kink}}L_3/T_{\mathrm{conf}}\). Only under the additional double-string tension estimate \(T_{\mathrm{conf}}\simeq2T_{\mathrm{kink}}\) does this become \(L\gtrsim2L_3\).

\textbf{Premises.}
\begin{align*}
(P1)\quad & \vec\sigma(x,x_3+L_3)=P_W^{-1}\vec\sigma(x,x_3).\\
(P2)\quad & P_W\vec\rho=\vec\rho-N\vec\mu_1.\\
(P3)\quad & \text{The }\vec\nu_1=\vec\mu_1\text{ component of the fundamental Wilson loop imposes }\oint_{C'}d\vec\sigma=2\pi\vec\mu_1.\\
(P4)\quad & (\Delta\vec\sigma)_{\mathrm{upper}}:=\frac{2\pi}{N}\vec\rho.\\
(P5)\quad & (\Delta\vec\sigma)_{\mathrm{lower}}:=-\frac{2\pi}{N}\vec\rho+2\pi\vec\mu_1.\\
(P6)\quad & \langle W(C)\rangle_{\mathrm{area}}\sim e^{-T_{\mathrm{conf}}\operatorname{Area}(C)},\quad T_{\mathrm{conf}}>0.\\
(P7)\quad & \langle W(C)\rangle_{\mathrm{wrap}}\sim e^{-T_{\mathrm{kink}}L_3\operatorname{Length}(C)},\quad T_{\mathrm{kink}}>0,\quad L_3>0.\\
(P8)\quad & \text{For a square loop of side }L,\\ 
&\operatorname{Area}(C)=L^2,\quad \operatorname{Length}(C)=4L,\quad L>0.\\
(P9)\quad & T_{\mathrm{conf}}\simeq2T_{\mathrm{kink}}\text{ is an extra tension estimate, not required for the SU(}N\text{) gluing identity.}
\end{align*}

\textbf{Derivation.}
The total jump around the Wilson-loop defect is
\begin{align*}
(\Delta\vec\sigma)_{\mathrm{upper}}+(\Delta\vec\sigma)_{\mathrm{lower}}
&=\frac{2\pi}{N}\vec\rho+\left(-\frac{2\pi}{N}\vec\rho+2\pi\vec\mu_1\right) && \text{by (P4), (P5)}\\
&=2\pi\vec\mu_1. && \text{cancellation}
\end{align*}
Hence
\begin{align*}
\oint_{C'}d\vec\sigma
&=(\Delta\vec\sigma)_{\mathrm{upper}}+(\Delta\vec\sigma)_{\mathrm{lower}} && \text{kink decomposition}\\
&=2\pi\vec\mu_1, && \text{previous line}
\end{align*}
which matches the fundamental Wilson-loop condition (P3). The lower jump is the Weyl-twisted gluing of the oppositely oriented upper jump:
\begin{align*}
P_W\left(-(\Delta\vec\sigma)_{\mathrm{upper}}\right)
&=P_W\left(-\frac{2\pi}{N}\vec\rho\right) && \text{by (P4)}\\
&=-\frac{2\pi}{N}P_W\vec\rho && \text{linearity}\\
&=-\frac{2\pi}{N}(\vec\rho-N\vec\mu_1) && \text{by (P2)}\\
&=-\frac{2\pi}{N}\vec\rho+2\pi\vec\mu_1 && \text{algebra}\\
&=(\Delta\vec\sigma)_{\mathrm{lower}}. && \text{by (P5)}
\end{align*}
Thus the wrapped wall is compatible with the center-twisted compactification. Summing the two semiclassical contributions gives
\begin{align*}
\langle W(C)\rangle
&\sim \langle W(C)\rangle_{\mathrm{area}}+\langle W(C)\rangle_{\mathrm{wrap}} && \text{two dominant configurations}\\
&\sim e^{-T_{\mathrm{conf}}\operatorname{Area}(C)}+e^{-T_{\mathrm{kink}}L_3\operatorname{Length}(C)}. && \text{by (P6), (P7)}
\end{align*}
The perimeter contribution dominates when its exponent is less negative:
\begin{align*}
e^{-T_{\mathrm{kink}}L_3\operatorname{Length}(C)}&>e^{-T_{\mathrm{conf}}\operatorname{Area}(C)} && \text{dominance criterion}\\
&\Longleftrightarrow T_{\mathrm{kink}}L_3\operatorname{Length}(C)<T_{\mathrm{conf}}\operatorname{Area}(C). && \text{monotonicity of }e^x
\end{align*}
For a square loop,
\begin{align*}
T_{\mathrm{kink}}L_3(4L)&<T_{\mathrm{conf}}L^2 && \text{by (P8)}\\
4T_{\mathrm{kink}}L_3&<T_{\mathrm{conf}}L && \text{divide by }L>0\\
L&>\frac{4T_{\mathrm{kink}}L_3}{T_{\mathrm{conf}}}. && \text{divide by }T_{\mathrm{conf}}>0
\end{align*}
If the additional estimate in (P9) is imposed, then
\begin{align*}
\frac{4T_{\mathrm{kink}}L_3}{T_{\mathrm{conf}}}
&\simeq \frac{4T_{\mathrm{kink}}L_3}{2T_{\mathrm{kink}}} && \text{use }T_{\mathrm{conf}}\simeq2T_{\mathrm{kink}}\\
&=2L_3. && \text{cancel }T_{\mathrm{kink}}
\end{align*}

\textbf{Final Result.}
\[
\boxed{\langle W(C)\rangle\sim e^{-T_{\mathrm{conf}}\operatorname{Area}(C)}+e^{-T_{\mathrm{kink}}L_3\operatorname{Length}(C)},\quad L_{\mathrm{switch}}=\frac{4T_{\mathrm{kink}}L_3}{T_{\mathrm{conf}}}\;\left(\simeq2L_3\text{ only if }T_{\mathrm{conf}}\simeq2T_{\mathrm{kink}}\right).}
\]
\hfill$\blacksquare$

core_reasoning_9:
\textbf{Claim.} In the small-\(L_3\) asymptotic form of the bion quasi-moduli integral for SU(2), the large-\(\rho_*\) magnetic-bion remnant satisfies
\[
\rho_*\simeq \frac{L_3}{2\pi}W_0\left(16\pi\left(\frac{4\pi L_4}{g^2L_3}\right)^2\right),
\]
where \(W_0\) is the principal Lambert \(W\)-function.

\textbf{Premises.}
\begin{align*}
(P1)\quad & \omega:=\frac{\pi}{L_3},\quad u:=\omega\rho,
\quad A:=\frac{32\pi L_4}{g^2L_3},
\quad L_3>0,
\quad L_4>0,
\quad g^2>0.\\
(P2)\quad & \text{In the large-}\rho\text{ small-}L_3\text{ approximation, the exponent near }x_3=L_3\text{ is }S(u):=-A\sqrt{\frac{\pi}{2u}}e^{-u}-2u.\\
(P3)\quad & \text{The saddle obeys }S'(u_*)=0\text{ with }u_*\gg1.\\
(P4)\quad & \frac{d}{du}\left(u^{-1/2}e^{-u}\right)=-e^{-u}\left(u^{-1/2}+\frac{1}{2}u^{-3/2}\right).\\
(P5)\quad & u_*\gg1\Longrightarrow u_*^{-1/2}+\frac{1}{2}u_*^{-3/2}\simeq u_*^{-1/2}.\\
(P6)\quad & W_0(X)e^{W_0(X)}=X\quad (X>0).\\
(P7)\quad & \rho_*=u_*/\omega.
\end{align*}

\textbf{Derivation.}
Differentiate the exponent:
\begin{align*}
S'(u)
&=-A\sqrt{\frac{\pi}{2}}\frac{d}{du}\left(u^{-1/2}e^{-u}\right)-2 && \text{by (P2)}\\
&=A\sqrt{\frac{\pi}{2}}e^{-u}\left(u^{-1/2}+\frac{1}{2}u^{-3/2}\right)-2. && \text{by (P4)}
\end{align*}
The saddle condition gives
\begin{align*}
0=S'(u_*)
&\Longleftrightarrow 2=A\sqrt{\frac{\pi}{2}}e^{-u_*}\left(u_*^{-1/2}+\frac{1}{2}u_*^{-3/2}\right) && \text{by (P3)}\\
&\simeq A\sqrt{\frac{\pi}{2}}e^{-u_*}u_*^{-1/2}. && \text{by (P5)}
\end{align*}
Rearrange this approximate equation:
\begin{align*}
2&\simeq A\sqrt{\frac{\pi}{2}}e^{-u_*}u_*^{-1/2} && \text{previous line}\\
e^{u_*}u_*^{1/2}&\simeq \frac{A}{2}\sqrt{\frac{\pi}{2}} && \text{multiply by }e^{u_*}u_*^{1/2}/2\\
e^{2u_*}u_*&\simeq \frac{A^2\pi}{8} && \text{square both sides}\\
(2u_*)e^{2u_*}&\simeq \frac{A^2\pi}{4}. && \text{multiply by }2
\end{align*}
Apply the principal Lambert function:
\begin{align*}
2u_*&\simeq W_0\left(\frac{A^2\pi}{4}\right) && \text{by (P6)}\\
u_*&\simeq \frac{1}{2}W_0\left(\frac{A^2\pi}{4}\right). && \text{divide by }2
\end{align*}
Substitute \(A=32\pi L_4/(g^2L_3)\):
\begin{align*}
\frac{A^2\pi}{4}
&=\frac{\pi}{4}\left(\frac{32\pi L_4}{g^2L_3}\right)^2 && \text{by (P1)}\\
&=256\pi^3\frac{L_4^2}{g^4L_3^2} && \text{arithmetic}\\
&=16\pi\left(\frac{4\pi L_4}{g^2L_3}\right)^2. && \text{factorization}
\end{align*}
Finally,
\begin{align*}
\rho_*
&=\frac{u_*}{\omega} && \text{by (P7)}\\
&\simeq \frac{1}{2\omega}W_0\left(16\pi\left(\frac{4\pi L_4}{g^2L_3}\right)^2\right) && \text{substitute }u_*\\
&=\frac{L_3}{2\pi}W_0\left(16\pi\left(\frac{4\pi L_4}{g^2L_3}\right)^2\right). && \text{by }\omega=\pi/L_3
\end{align*}

\textbf{Final Result.}
\[
\boxed{\rho_*\simeq \frac{L_3}{2\pi}W_0\left(16\pi\left(\frac{4\pi L_4}{g^2L_3}\right)^2\right).}
\]
\hfill$\blacksquare$

core_reasoning_10:
\textbf{Claim.} For the supersymmetric bion quasi-moduli integrand on \(R^2\times S^1\times S^1\), harmonicity of \(V_b(\rho,x_3)\) away from the regulated core implies the pointwise identity
\[
\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)e^{-2V_b}=\frac{1}{4}\nabla^2e^{-2V_b}.
\]
Thus the bion amplitude is a boundary term; if the \(x_3\)-periodic boundaries cancel and the regulated radial boundary term vanishes, then \(Z_{\mathrm{bion}}=0\).

\textbf{Premises.}
\begin{align*}
(P1)\quad & V_b=V_b(\rho,x_3),\quad \rho>0,
\quad \nabla^2:=\partial_3^2+\partial_\rho^2+\frac{1}{\rho}\partial_\rho.\\
(P2)\quad & \nabla^2V_b=0\quad \text{away from the regulated core}.\\
(P3)\quad & F:=e^{-2V_b}.\\
(P4)\quad & Z_{\mathrm{bion}}=C_b\int_{\rho_{\min}}^{\infty}d\rho\int_0^{2L_3}dx_3\,\rho\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)e^{-2V_b},\\
& C_b\text{ is independent of }\rho,x_3.\\
(P5)\quad & V_b(\rho,x_3+2L_3)=V_b(\rho,x_3).\\
(P6)\quad & \left[\rho\partial_\rho F\right]_{\rho_{\min}}^{\infty}=0\quad \text{after neutral-bion core regularization and large-}\rho\text{ decay}.\\
(P7)\quad & \partial_a e^{-2V_b}=-2e^{-2V_b}\partial_aV_b\quad (a\in\{3,\rho\}).
\end{align*}

\textbf{Derivation.}
First compute derivatives of \(F\):
\begin{align*}
\partial_aF
&=-2e^{-2V_b}\partial_aV_b && \text{by (P3), (P7)}\\
\partial_a^2F
&=4e^{-2V_b}(\partial_aV_b)^2-2e^{-2V_b}\partial_a^2V_b,
\quad a\in\{3,\rho\}. && \text{differentiate the previous line}
\end{align*}
The Laplacian of \(F\) is therefore
\begin{align*}
\nabla^2F
&=\partial_3^2F+\partial_\rho^2F+\frac{1}{\rho}\partial_\rho F && \text{by (P1)}\\
&=4e^{-2V_b}\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)\\
&\quad -2e^{-2V_b}\left(\partial_3^2V_b+\partial_\rho^2V_b+\frac{1}{\rho}\partial_\rho V_b\right) && \text{substitute derivatives}\\
&=4e^{-2V_b}\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)-2e^{-2V_b}\nabla^2V_b && \text{by (P1)}\\
&=4e^{-2V_b}\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right). && \text{by (P2)}
\end{align*}
Hence
\begin{align*}
\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)e^{-2V_b}
&=\frac{1}{4}\nabla^2F && \text{divide by }4\\
&=\frac{1}{4}\nabla^2e^{-2V_b}. && \text{by (P3)}
\end{align*}
Substituting this identity into the quasi-moduli integral gives
\begin{align*}
Z_{\mathrm{bion}}
&=\frac{C_b}{4}\int_{\rho_{\min}}^{\infty}d\rho\int_0^{2L_3}dx_3\,\rho\nabla^2F && \text{by (P4)}\\
&=\frac{C_b}{4}\int_{\rho_{\min}}^{\infty}d\rho\int_0^{2L_3}dx_3\,\rho\left(\partial_3^2F+\partial_\rho^2F+\frac{1}{\rho}\partial_\rho F\right) && \text{by (P1)}\\
&=\frac{C_b}{4}\int_{\rho_{\min}}^{\infty}d\rho\int_0^{2L_3}dx_3\left(\partial_3(\rho\partial_3F)+\partial_\rho(\rho\partial_\rho F)\right). && \rho\text{ independent of }x_3
\end{align*}
The \(x_3\)-boundary term cancels because
\begin{align*}
\int_0^{2L_3}dx_3\,\partial_3(\rho\partial_3F)
&=\rho\partial_3F(\rho,2L_3)-\rho\partial_3F(\rho,0) && \text{fundamental theorem}\\
&=0, && \text{by (P5), (P3)}
\end{align*}
and the radial boundary term is
\begin{align*}
\int_{\rho_{\min}}^{\infty}d\rho\,\partial_\rho(\rho\partial_\rho F)
&=\left[\rho\partial_\rho F\right]_{\rho_{\min}}^{\infty} && \text{fundamental theorem}\\
&=0. && \text{by (P6)}
\end{align*}
Consequently
\begin{align*}
Z_{\mathrm{bion}}&=0. && \text{all boundary terms cancel or vanish under (P5), (P6)}
\end{align*}

\textbf{Final Result.}
\[
\boxed{\left((\partial_3V_b)^2+(\partial_\rho V_b)^2\right)e^{-2V_b}=\frac{1}{4}\nabla^2e^{-2V_b},\qquad Z_{\mathrm{bion}}=0\text{ under (P5), (P6)}.}
\]
\hfill$\blacksquare$
